// ErrPending is wrapped by *Error when a requested score is not final yet (VMAFX_PENDING).
var ErrPending = errors.New("vmafx: VMAFX_PENDING")

// Error represents a non-OK VMAFx API result with structured diagnostics.
type Error struct {
	Function string
	Status   Status
	Message  string
	Subject  string
	Errno    int32
}

func (e *Error) Error() string {
	if e.Subject != "" {
		return fmt.Sprintf("%s: %s: %s [%s]", e.Function, e.Status, e.Message, e.Subject)
	}
	if e.Message != "" {
		return fmt.Sprintf("%s: %s: %s", e.Function, e.Status, e.Message)
	}
	return fmt.Sprintf("%s: %s", e.Function, e.Status)
}

func (e *Error) Unwrap() error {
	if e.Status == StatusPending {
		return ErrPending
	}
	return e.Status.Err()
}

func freeCString(p *C.char) {
	// SAFETY: p was allocated by C.CString and is freed once after the C call returns.
	C.free(unsafe.Pointer(p))
}

func checkStatus(status Status, cErr *C.VmafxError, function string) error {
	if status == StatusOK {
		return nil
	}
	var message, subject string
	var errnoVal int32
	if cErr != nil {
		message = C.GoString(C.vmafx_error_message(cErr))
		subject = C.GoString(C.vmafx_error_subject(cErr))
		errnoVal = int32(C.vmafx_error_errno(cErr))
		C.vmafx_error_free(cErr)
	}
	return &Error{
		Function: function,
		Status:   status,
		Message:  message,
		Subject:  subject,
		Errno:    errnoVal,
	}
}

