// Context wraps a VmafxContext handle; close it with Close.
type Context struct {
	handle *C.VmafxContext
}

// New creates a VmafxContext; pass nil for default configuration.
func New(config *ContextConfig) (*Context, error) {
	var raw C.VmafxContextConfig
	var cfgPtr *C.VmafxContextConfig
	if config != nil {
		raw = config.toC()
		cfgPtr = &raw
	}
	var handle *C.VmafxContext
	var cErr *C.VmafxError
	status := Status(C.vmafx_context_create(cfgPtr, &handle, &cErr))
	if err := checkStatus(status, cErr, "vmafx_context_create"); err != nil {
		return nil, err
	}
	return &Context{handle: handle}, nil
}

// NewContext creates a VmafxContext; alias for New.
func NewContext(config *ContextConfig) (*Context, error) {
	return New(config)
}

func (c *Context) rawHandle() *C.VmafxContext {
	if c == nil {
		return nil
	}
	return c.handle
}

// Close destroys the context; on failure it stays open and Close may be retried (ADR-1336).
func (c *Context) Close() error {
	if c == nil || c.handle == nil {
		return nil
	}
	var cErr *C.VmafxError
	status := Status(C.vmafx_context_destroy(c.handle, &cErr))
	if err := checkStatus(status, cErr, "vmafx_context_destroy"); err != nil {
		return err
	}
	c.handle = nil
	return nil
}

// LibvmafHandle returns the libvmaf VmafContext pointer bound to this context.
// SAFETY: vmafx_context_libvmaf_handle returns an opaque borrowed C pointer; nil returns nil.
func (c *Context) LibvmafHandle() unsafe.Pointer {
	// SAFETY: the conversion only retypes the borrowed pointer; nothing is dereferenced.
	return unsafe.Pointer(C.vmafx_context_libvmaf_handle(c.rawHandle()))
}

// Provenance: Fill the provenance record of a context.
func (c *Context) Provenance() (Provenance, error) {
	var out C.VmafxProvenance
	// SAFETY: unsafe.Sizeof is evaluated at compile time and dereferences nothing.
	out.struct_size = C.uint32_t(unsafe.Sizeof(out))
	var cErr *C.VmafxError
	status := Status(C.vmafx_context_provenance(c.rawHandle(), &out, &cErr))
	if err := checkStatus(status, cErr, "vmafx_context_provenance"); err != nil {
		return Provenance{}, err
	}
	return provenanceFromC(out), nil
}

